public static class CommandLineArgumentParser
{
    public static Dictionary<string, string?> Parse(string[] args)
    {
        ArgumentNullException.ThrowIfNull(args);
        var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

        for (var i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            if (arg.Equals("census", StringComparison.OrdinalIgnoreCase))
            {
                dict["AutoWrongCensus:Command"] = "census";
                if (i + 1 < args.Length)
                {
                    dict["AutoWrongCensus:TracePath"] = args[++i];
                }
            }
            else if (arg.Equals("pairs", StringComparison.OrdinalIgnoreCase))
            {
                dict["AutoWrongCensus:Command"] = "pairs";
                if (i + 1 < args.Length)
                {
                    dict["AutoWrongCensus:CensusTsvPath"] = args[++i];
                }
                if (i + 1 < args.Length)
                {
                    dict["AutoWrongCensus:PairsTracePath"] = args[++i];
                }
            }
            else if (arg.Equals("--trace", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
            {
                dict["AutoWrongCensus:TracePath"] = args[++i];
            }
            else if (arg.StartsWith("--trace=", StringComparison.OrdinalIgnoreCase))
            {
                dict["AutoWrongCensus:TracePath"] = arg["--trace=".Length..];
            }
            else if (arg.Equals("--census", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
            {
                dict["AutoWrongCensus:CensusTsvPath"] = args[++i];
            }
            else if (arg.StartsWith("--census=", StringComparison.OrdinalIgnoreCase))
            {
                dict["AutoWrongCensus:CensusTsvPath"] = arg["--census=".Length..];
            }
        }

        return dict;
    }
}
