{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Minimal legacy parser for the two subcommands used by <c>tools/LetUsCook.AutoWrongCensus</c>.
/// The parser is intentionally small; callers hard-code the flags (see <c>Makefile</c>).
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Parses <c>census &lt;trace&gt;</c> and <c>pairs &lt;census&gt; &lt;trace&gt;</c>.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>Configuration key/value pairs for options binding.</returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 0)
		{
			return dict;
		}

		var command = args[0].Trim().ToLowerInvariant();

		if (command == "census" && args.Length >= 2)
		{
			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
			return dict;
		}

		if (command == "pairs" && args.Length >= 3)
		{
			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
			return dict;
		}

		// Unrecognised invocation — return empty; the runner will emit usage and exit 1.
		return dict;
	}
}
