{"content":"using System.Reflection;
using System.Text.Json;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Loads the <c>exact-overrides.json</c> key set from the FDC assembly (production data file) so the
/// census can answer "is the normalized rawText a key in exact-overrides.json" without copying matcher
/// logic (D-014). The file lives in <c>LetUsCook.Fdc.Lexicon.Resources</c> and is embedded as a manifest
/// resource.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly HashSet<string> _keys;

	/// <summary>Creates the index from the embedded <c>exact-overrides.json</c> resource.</summary>
	public ExactOverrideKeyIndex()
	{
		var asm = typeof(LetUsCook.Fdc.Lexicon.FdcNormalizer).Assembly;
		var name = asm.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = asm.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var json = reader.ReadToEnd();

		var map = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(json, new JsonSerializerOptions(JsonSerializerDefaults.Web))
			?? new Dictionary<string, JsonElement>();

		_keys = new HashSet<string>(map.Keys, StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Returns true when the normalized raw text is a key in <c>exact-overrides.json</c>.</summary>
	/// <param name="rawText">The raw ingredient line text.</param>
	/// <returns>True if the key exists.</returns>
	public bool ContainsNormalizedRaw(string rawText)
	{
		if (string.IsNullOrWhiteSpace(rawText))
		{
			return false;
		}

		var trimmed = rawText.Trim().ToLowerInvariant();
		var cut = trimmed.IndexOf('(');
		if (cut >= 0)
		{
			trimmed = trimmed[..cut].Trim();
		}

		return _keys.Contains(trimmed);
	}
}
