{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;
using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies every auto-wrong trace line by accepted-row vs key-row relation and decision site.
/// All matching logic is delegated to the production helpers (D-014): <see cref="FdcNormalizer"/>,
/// <see cref="FdcMatcher"/>, <see cref="FdcDescriptionParser"/>, <see cref="IngredientLineResolver"/>,
/// and the lexicon sets shipped with LetUsCook.Fdc.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleToken = new(1);

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies a trace line; only auto-wrong lines are meaningful.</summary>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = PickAtom(line.Atoms);
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var keyType = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var accDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var accType = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyHeadPhrase = KeyHeadPhraseTokens(keyDesc, keyType);
		var accHeadPhrase = KeyHeadPhraseTokens(accDesc, accType);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);

		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType));
		var accHeadParsed = FdcDescriptionParser.Parse(accDesc, DatasetOf(accType));

		var keyHeadNorm = NormTokens(keyHeadParsed.HeadTerm);
		var accHeadNorm = NormTokens(accHeadParsed.HeadTerm);

		var parsedNorm = NormTokens(atom?.ParsedName ?? string.Empty);

		var keyTier = keyType;
		var accTier = accType;

		string relation = string.Empty;
		string site = string.Empty;
		string overrideKey = string.Empty;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		// 1. no-label
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = "no-label";
		}
		else
		{
			// 2. pack-unit-state
			if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (accState & FoodState.Canned) == 0)
			{
				relation = "pack-unit-state";
			}
			else
			{
				// 3. compound-head-lost
				if (keyHeadPhrase.Count >= 2 && parsedNorm.Count >= 1 && parsedNorm.Count == 1)
				{
					var first = IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]);
					if (string.Equals(parsedNorm[0], first, StringComparison.OrdinalIgnoreCase))
					{
						relation = "compound-head-lost";
					}
				}
			}
		}

		// 4/5/6/7/8 — only evaluated when relation is still empty and the key exists
		if (string.IsNullOrEmpty(relation) && !string.IsNullOrWhiteSpace(keyDesc))
		{
			bool headsAgree = HeadsAgree(keyHeadNorm, accHeadNorm);

			if (headsAgree)
			{
				// 4. state-mismatch
				if (keyState != accState)
				{
					relation = "state-mismatch";
				}
				else if (string.IsNullOrWhiteSpace(keyType) || string.IsNullOrWhiteSpace(accType))
				{
					relation = "other";
					missingField = string.IsNullOrWhiteSpace(accType) ? "actualDataTypes" : "expectedDataTypes";
				}
				else if (!string.Equals(keyType, accType, StringComparison.OrdinalIgnoreCase))
				{
					relation = "row-choice-tier";
				}
				else
				{
					// 6. same-head-other-qualifier
					relation = "same-head-other-qualifier";
					var keyQual = NormTokensList(keyHeadParsed.Qualifiers);
					var accQual = NormTokensList(accHeadParsed.Qualifiers);
					var keySet = new HashSet<string>(keyQual, StringComparer.OrdinalIgnoreCase);
					var accSet = new HashSet<string>(accQual, StringComparer.OrdinalIgnoreCase);
					keyOnlyQualifiers = keySet.Except(accSet, StringComparer.OrdinalIgnoreCase).ToArray();
					acceptedOnlyQualifiers = accSet.Except(keySet, StringComparer.OrdinalIgnoreCase).ToArray();
				}
			}
			else
			{
				// 7. sibling-food
				relation = "sibling-food";
			}
		}

		// If relation is still empty (e.g. key present but heads empty and state equal), fall to other.
		if (string.IsNullOrEmpty(relation))
		{
			relation = "other";
		}

		// Site
		if (atom is not null)
		{
			var path = atom.Path ?? string.Empty;
			if (path.Equals("override", StringComparison.OrdinalIgnoreCase))
			{
				site = "override";
				var normalizedRaw = NormalizeForOverrideKey(line.RawText);
				overrideKey = _overrideKeys.IsKey(normalizedRaw) ? "yes" : "no";
			}
			else if (path.Equals("curated", StringComparison.OrdinalIgnoreCase))
			{
				site = "curated";
			}
			else if (path.Equals("ranker", StringComparison.OrdinalIgnoreCase))
			{
				site = atom.Reused ? "reuse" : "ranker";
			}
			else
			{
				site = "unknown";
			}
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = accTier,
			KeyTier = keyTier,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	private static TraceAtom? PickAtom(IReadOnlyList<TraceAtom> atoms)
	{
		if (atoms.Count == 0) return null;
		var accepted = atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase));
		return accepted ?? atoms[0];
	}

	private IReadOnlyList<string> KeyHeadPhraseTokens(string desc, string dataType)
	{
		var tokens = _normalizer.NormalizeToTokens(desc);
		var phrase = new List<string>();
		foreach (var tok in tokens)
		{
			if (IsStateWord(tok))
				break;
			phrase.Add(IngredientLineResolver.SingularizeToken(tok));
		}
		return phrase;
	}

	private bool IsStateWord(string tok)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(tok, StringComparer.OrdinalIgnoreCase))
			return true;

		_singleToken.Clear();
		_singleToken.Add(tok);
		var state = FdcMatcher.ExtractCandidateState(_singleToken);
		var sat = FdcMatcher.ExtractCandidateSatisfiers(_singleToken);
		return state != FoodState.None || sat != FoodState.None;
	}

	private static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		if (tokens.Count == 0) return FoodState.None;
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	private static IReadOnlyList<string> NormTokens(string? text)
	{
		if (string.IsNullOrWhiteSpace(text)) return [];
		var normalizer = new FdcNormalizer();
		return normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();
	}

	private static IReadOnlyList<string> NormTokensList(IReadOnlyList<string> list)
	{
		if (list.Count == 0) return [];
		var normalizer = new FdcNormalizer();
		var outList = new List<string>(list.Count);
		foreach (var s in list)
		{
			foreach (var t in normalizer.NormalizeToTokens(s))
			{
				outList.Add(IngredientLineResolver.SingularizeToken(t));
			}
		}
		return outList;
	}

	private static bool HeadsAgree(IReadOnlyList<string> a, IReadOnlyList<string> b)
	{
		if (a.Count != b.Count) return false;
		for (int i = 0; i < a.Count; i++)
		{
			if (!string.Equals(a[i], b[i], StringComparison.OrdinalIgnoreCase))
				return false;
		}
		return true;
	}

	private static FdcDataset DatasetOf(string? dataType)
	{
		if (string.IsNullOrWhiteSpace(dataType)) return FdcDataset.None;
		return Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var d) ? d : FdcDataset.None;
	}

	private static string NormalizeForOverrideKey(string raw)
	{
		if (string.IsNullOrWhiteSpace(raw)) return string.Empty;
		var lower = raw.Trim().ToLowerInvariant();
		var idx = lower.IndexOf('(');
		if (idx >= 0) lower = lower[..idx];
		return lower.Trim();
	}
}
