{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies every auto-wrong trace line on two axes: the relation between the accepted row and the
/// key row, and the decision site that shipped the wrong row. All matching helpers are the production
/// code (D-014) — no copies of matcher logic.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideIndex;
	private readonly string?[] _singleTokenScratch = new string?[1];

	/// <summary>Initialises the classifier with production helpers.</summary>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideIndex)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideIndex = overrideIndex ?? throw new ArgumentNullException(nameof(overrideIndex));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Combines <see cref="FdcMatcher.ExtractCandidateState"/> and <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>.</summary>
	private static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		var state = FdcMatcher.ExtractCandidateState(tokens);
		var sat = FdcMatcher.ExtractCandidateSatisfiers(tokens);
		return state | sat;
	}

	/// <summary>Normalises a free-form text into singularised tokens.</summary>
	private IReadOnlyList<string> SingularPhrase(string? text)
	{
		if (string.IsNullOrWhiteSpace(text))
		{
			return [];
		}

		var tokens = _normalizer.NormalizeToTokens(text);
		var result = new List<string>(tokens.Count);
		foreach (var t in tokens)
		{
			result.Add(IngredientLineResolver.SingularizeToken(t));
		}

		return result;
	}

	/// <summary>Returns <see langword="true"/> when <paramref name="token"/> is a production state/modifier word.</summary>
	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		var state = FdcMatcher.ExtractCandidateState(_singleTokenScratch);
		if (state != FoodState.None)
		{
			return true;
		}

		var sat = FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch);
		return sat != FoodState.None;
	}

	/// <summary>Key head phrase: tokens from the start of the key description up to (but not including) the first state/modifier token.</summary>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var t in tokens)
		{
			if (CarriesStateToken(t))
			{
				break;
			}

			phrase.Add(t);
		}

		return phrase;
	}

	/// <summary>Maps a dataset string to <see cref="FdcDataset"/>; unknown values map to <see cref="FdcDataset.None"/>.</summary>
	private static FdcDataset DatasetOf(string? s) =>
		Enum.TryParse<FdcDataset>(s, ignoreCase: true, out var d) ? d : FdcDataset.None;

	/// <summary>Classifies one auto-wrong trace line.</summary>
	public ClassificationResult Classify(TraceLine line)
	{
		if (line is null)
		{
			throw new ArgumentNullException(nameof(line));
		}

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var accDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyType = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var accType = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault()
			?? new TraceAtom();

		var parsedName = atom.ParsedName ?? string.Empty;
		var path = atom.Path ?? string.Empty;
		var reused = atom.Reused;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);

		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType));
		var accParsed = FdcDescriptionParser.Parse(accDesc, DatasetOf(accType));

		var keyHeadNorm = SingularPhrase(keyParsed.HeadTerm);
		var accHeadNorm = SingularPhrase(accParsed.HeadTerm);

		var parsedNorm = SingularPhrase(parsedName);

		var keyPhrase = KeyHeadPhrase(keyTokens);

		string relation;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? accOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = "no-label";
		}
		else if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (accState & FoodState.Canned) == 0)
		{
			relation = "pack-unit-state";
		}
		else if (keyPhrase.Count >= 2 && parsedNorm.Count == 1)
		{
			var first = IngredientLineResolver.SingularizeToken(keyPhrase[0]);
			if (string.Equals(parsedNorm[0], first, StringComparison.OrdinalIgnoreCase))
			{
				relation = "compound-head-lost";
			}
			else
			{
				relation = ResolveHeads(keyHeadNorm, accHeadNorm, keyState, accState, keyType, accType, out missingField, out keyOnlyQualifiers, out accOnlyQualifiers);
			}
		}
		else
		{
			relation = ResolveHeads(keyHeadNorm, accHeadNorm, keyState, accState, keyType, accType, out missingField, out keyOnlyQualifiers, out accOnlyQualifiers);
		}

		string site;
		string overrideKey = string.Empty;

		if (string.Equals(path, "override", StringComparison.OrdinalIgnoreCase))
		{
			site = "override";
			var normalizedRaw = NormalizeForOverrideKey(line.RawText);
			overrideKey = _overrideIndex.IsKey(normalizedRaw) ? "yes" : "no";
		}
		else if (string.Equals(path, "curated", StringComparison.OrdinalIgnoreCase))
		{
			site = "curated";
		}
		else if (string.Equals(path, "ranker", StringComparison.OrdinalIgnoreCase))
		{
			site = reused ? "reuse" : "ranker";
		}
		else
		{
			site = "unknown-site";
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = accType,
			KeyTier = keyType,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = accOnlyQualifiers,
		};
	}

	private string ResolveHeads(
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> accHead,
		FoodState keyState,
		FoodState accState,
		string keyType,
		string accType,
		out string? missingField,
		out IReadOnlyList<string>? keyOnlyQualifiers,
		out IReadOnlyList<string>? accOnlyQualifiers)
	{
		missingField = null;
		keyOnlyQualifiers = null;
		accOnlyQualifiers = null;

		var headsAgree = keyHead.Count == accHead.Count
			&& keyHead.Zip(accHead, (k, a) => string.Equals(k, a, StringComparison.OrdinalIgnoreCase)).All(b => b);

		if (!headsAgree)
		{
			return "sibling-food";
		}

		if (keyState != accState)
		{
			return "state-mismatch";
		}

		if (string.IsNullOrWhiteSpace(keyType) || string.IsNullOrWhiteSpace(accType))
		{
			missingField = string.IsNullOrWhiteSpace(accType) ? "actualDataTypes" : "expectedDataTypes";
			return "other";
		}

		if (!string.Equals(keyType, accType, StringComparison.OrdinalIgnoreCase))
		{
			return "row-choice-tier";
		}

		var keyQual = SingularPhrase(string.Join(' ', keyHead));
		var accQual = SingularPhrase(string.Join(' ', accHead));
		var keyQualSet = new HashSet<string>(keyQual, StringComparer.OrdinalIgnoreCase);
		var accQualSet = new HashSet<string>(accQual, StringComparer.OrdinalIgnoreCase);

		var keyOnly = keyQualSet.Except(accQualSet).ToList();
		var accOnly = accQualSet.Except(keyQualSet).ToList();

		if (keyOnly.Count > 0 || accOnly.Count > 0)
		{
			keyOnlyQualifiers = keyOnly;
			accOnlyQualifiers = accOnly;
			return "same-head-other-qualifier";
		}

		return "other";
	}

	/// <summary>Normalises raw text for the exact-overrides lookup (lower-case, trimmed, content after the first <c>(</c> dropped).</summary>
	private static string NormalizeForOverrideKey(string raw)
	{
		if (string.IsNullOrWhiteSpace(raw))
		{
			return string.Empty;
		}

		var trimmed = raw.Trim();
		var idx = trimmed.IndexOf('(');
		if (idx >= 0)
		{
			trimmed = trimmed[..idx];
		}

		return trimmed.Trim().ToLowerInvariant();
	}
